import{_ as a,o as t,a as l,b as i}from"./app.DKoEZOcr.js";const r="/ascendc.github.io/pr/5487/assets/sync_async._S5Ec0NA.png",h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"SIMD算子实现","link":"/guide/operator_practice/simd_operator_impl/simd_operator_impl"},{"text":"矩阵编程（高阶API）","link":"/guide/operator_practice/simd_operator_impl/matrix_advanced_api/matrix_advanced_api"},{"text":"特性场景","link":"/guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/matmul_features"},{"text":"异步场景处理","link":"/guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/async_scenario"}]},"headers":[],"relativePath":"guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/async_scenario.md","filePath":"guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/async_scenario.md","outlineHeaders":[{"level":2,"title":"功能介绍","slug":"功能介绍","link":"#功能介绍"},{"level":2,"title":"使用场景","slug":"使用场景","link":"#使用场景"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1787050286000}'),s={name:"guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/async_scenario.md"};function n(p,e,c,o,m,d){return t(),l("div",null,[...e[0]||(e[0]=[i('<div><article class="markdown-body"><h1>异步场景处理<span id="ZH-CN_TOPIC_0000002532388133"></span></h1><h2 id="功能介绍">功能介绍<span id="zh-cn_topic_0000002264077888_section310824820358"></span><a class="header-anchor" href="#功能介绍">​</a></h2><p>Matmul的<a href="../../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/Iterate.html">Iterate</a>和<a href="../../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/IterateAll.html">IterateAll</a>接口在MIX场景（包含矩阵计算和矢量计算）下提供了同步和异步两种模式，纯Cube场景（只有矩阵计算）下，只支持同步模式。</p><p>同步模式指的是程序执行时，需要等待某个操作完成后才能继续执行下一步操作。 异步模式指的是程序执行时，不需要等待某个操作完成就可以继续执行下一步操作。</p><ul><li><p>Iterate&amp;GetTensorC的同步和异步</p><ul><li><p>同步：执行完一次Iterate迭代计算后，执行<a href="../../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/GetTensorC.html">GetTensorC</a>搬运矩阵C分片，搬运完成后，才能进行下一次计算。如下图所示，C矩阵中，矩阵块1搬走后，才能计算矩阵块2，矩阵块2搬运完成后，才能计算矩阵块3。</p><p><img src="'+r+`" alt></p><p>Iterate&amp;GetTensorC同步模式的关键代码示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>while (mm.Iterate()) {
    mm.GetTensorC(gm_c);
}
</code></pre></div></li><li><p>异步：通过设置Iterate接口的模板参数开启异步模式。调用Iterate后，无需立即调用GetTensorC同步等待矩阵C分块搬运完成，可以先执行其它操作，待需要获取结果时再调用GetTensorC。异步模式可以减少同步等待，提高并行度，开发者对计算性能要求较高时，可以选用该方式。异步场景时，需要使用一块临时空间来缓存Iterate计算结果，否则会覆盖计算结果，调用GetTensorC时会在该临时空间中获取C的矩阵分片。临时空间通过<a href="../../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/SetWorkspace.html">SetWorkspace</a>接口进行设置。SetWorkspace接口需要在Iterate接口之前调用。</p><p>Iterate&amp;GetTensorC异步模式的关键代码示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>mm.SetWorkspace(workspace, size); // 其中，workspace为临时空间的物理地址，size为singleCoreM * singleCoreN的矩阵C大小
// 异步模式
mm.template Iterate&lt;false&gt;();
……// 执行其他操作
auto mIter = Ceil(singleCoreM, baseM);
auto nIter = Ceil(singleCoreN, baseN);
for (int i = 0; i &lt; mIter * nIter ; ++i) {
    mm.GetTensorC&lt;false&gt; (gm_c);
}
</code></pre></div></li></ul></li><li><p>IterateAll的同步和异步</p><ul><li><p>同步：后续操作需要同步等待IterateAll执行结束。</p><p>IterateAll同步模式的关键代码示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>mm.SetTensorA(gm_a);    // 设置左矩阵A
mm.SetTensorB(gm_b);    // 设置右矩阵B
mm.SetBias(gm_bias);    // 设置Bias
mm.IterateAll(gm_c);
// 后续操作
...
</code></pre></div></li><li><p>异步：后续操作不需要同步等待IterateAll执行结束，需要IterateAll的结果时，调用<a href="../../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/WaitIterateAll.html">WaitIterateAll</a>等待IterateAll异步接口返回。</p><p>IterateAll异步模式的关键代码示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>AscendC::Matmul&lt;aType, bType, cType, biasType&gt; mm;
mm.SetTensorA(queryGm[tensorACoreOffset]);
mm.SetTensorB(keyGm[tensorBCoreOffset + sInnerStart * singleProcessSInnerSize *
      tilingData-&gt;attentionScoreOffsetStrideParams.matmulHead], true);
mm.SetTail(singleProcessSOuterSize, mmNNum);
mm.template IterateAll&lt;false&gt;(workspaceGm[tmp_block_idx * mmResUbSize * sInnerLoopTimes],0, false,true);
// 执行其他操作
mm.WaitIterateAll(); // 等待IterateAll完成
DataCopy(dstUB, GM);  // 进行GM到Unified Buffer（UB）的拷贝
</code></pre></div></li></ul></li></ul><h2 id="使用场景">使用场景<span id="zh-cn_topic_0000002264077888_section118051016163613"></span><a class="header-anchor" href="#使用场景">​</a></h2><ul><li>Iterate&amp;GetTensorC的同步：MIX场景（包含矩阵计算和矢量计算）、纯Cube场景（只有矩阵计算）。</li><li>Iterate&amp;GetTensorC的异步：仅MIX场景（包含矩阵计算和矢量计算）。</li><li>IterateAll的同步：MIX场景（包含矩阵计算和矢量计算）、纯Cube场景（只有矩阵计算）。</li><li>IterateAll的异步：仅MIX场景（包含矩阵计算和矢量计算）。</li></ul><h2 id="约束说明">约束说明<span id="zh-cn_topic_0000002264077888_section14160134220363"></span><a class="header-anchor" href="#约束说明">​</a></h2><ul><li><p>Iterate&amp;GetTensorC的异步场景：</p><ul><li>传入的C矩阵地址空间大小需要保证不小于baseM * baseN。</li><li>SetWorkspace接口需要在Iterate接口之前调用。</li><li>支持只输出到UB（VECIN）、只输出到Global Memory，同时输出到Global Memory和UB（VECIN）三种输出方式。</li><li>取出C矩阵到UB（VECIN）时，数据格式仅支持NZ；取出C矩阵到GM时，数据格式支持ND或NZ。</li></ul></li><li><p>IterateAll的异步场景：</p><ul><li>传入的C矩阵地址空间大小需要保证不小于singleCoreM * singleCoreN。</li><li>仅支持连续输出至Global Memory。</li></ul></li></ul><h2 id="调用示例">调用示例<span id="zh-cn_topic_0000002264077888_section15486294368"></span><a class="header-anchor" href="#调用示例">​</a></h2><ul><li>Iterate&amp;GetTensorC的异步场景的完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/04_advanced_api/00_matmul/matmul_fused">异步场景样例</a>、<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/04_advanced_api/00_matmul/matmul_async_iterate">Iterate异步场景样例</a>。</li><li>IterateAll的异步场景的完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/04_advanced_api/00_matmul/matmul_async_iterate_all">IterateAll异步场景样例</a>。</li></ul></article></div>`,1)])])}const u=a(s,[["render",n]]);export{h as __pageData,u as default};
